async function showHistory(){const a=address(state.focus.r,state.focus.c),rows=await fetch(`/api/workbooks/${state.wb.id}/history?sheet=${encodeURIComponent(state.sheet.id)}&address=${a}`).then(r=>r.json());openPanel(`History · ${a}`,rows.length?rows.map(x=>`<div class="history-item"><b>${userName(x.userId)}</b> <span class="muted">${new Date(x.changedAt).toLocaleString()}</span><div><del>${html(x.previousValue)||'(blank)'}</del> → <ins>${html(x.newValue)||'(blank)'}</ins></div></div>`).join(''):'<p>No saved changes for this cell.</p>')}
function showRevisions(){openPanel('Revision history',state.revisions.map(r=>`<div class="revision-item"><b>Revision ${r.number}</b><div class="muted">${new Date(r.createdAt).toLocaleString()} · ${r.userId?userName(r.userId):'Initial seed'}</div><button data-preview="${r.number}">Preview</button><button data-restore="${r.number}">Restore as draft</button></div>`).join(''));document.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>previewRevision(+b.dataset.preview,false));document.querySelectorAll('[data-restore]').forEach(b=>b.onclick=()=>previewRevision(+b.dataset.restore,true))}
async function previewRevision(n,restore){const snap=await fetch(`/api/workbooks/${state.wb.id}/revisions/${n}`).then(r=>r.json()),cells=snap.sheets.find(s=>s.id===state.sheet.id)?.cells||{};if(restore){const keys=new Set([...Object.keys(state.cells),...Object.keys(cells)]),changes=[...keys].map(a=>({address:a,value:cells[a]||''}));apply(changes,`Restore revision ${n}`);message(`Revision ${n} restored as an unsaved draft`);$('panel').hidden=true}else openPanel(`Preview · Revision ${n}`,`<p>This preview is read-only.</p><pre>${html(JSON.stringify(cells,null,2))}</pre><button id="backRevisions">Back</button>`),setTimeout(()=>{const b=$('backRevisions');if(b)b.onclick=showRevisions})}
function openPanel(title,content){$('panelTitle').textContent=title;$('panelBody').innerHTML=content;$('panel').hidden=false}
function html(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function userName(id){return state.users.find(u=>u.id===id)?.name||id}

async function sendPresence(){if(!state.wb)return;fetch(`/api/workbooks/${state.wb.id}/presence`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({sessionId,userId:$('user').value,address:rangeAddress(),color})}).catch(()=>{})}
function renderRemote(){document.querySelectorAll('.remote').forEach(x=>x.remove());const legend=$('presenceLegend');legend.innerHTML='';const others=state.remote.filter(x=>x.sessionId!==sessionId),counts={};for(const p of state.remote)counts[p.userId]=(counts[p.userId]||0)+1;$('presenceSummary').textContent=Object.keys(counts).length?Object.entries(counts).map(([u,n])=>`${userName(u)} (${n})`).join(' · '):'Only you';others.forEach(p=>{const q=parseRangeText(p.address);if(!q)return;const r1=Math.min(q.a.r,q.b.r),r2=Math.max(q.a.r,q.b.r),c1=Math.min(q.a.c,q.b.c),c2=Math.max(q.a.c,q.b.c),d=document.createElement('div');d.className='remote';d.dataset.label=userName(p.userId);d.style.cssText=`--remote:${p.color};border-color:${p.color};left:${HW+(c1-1)*CW}px;top:${r1*RH}px;width:${(c2-c1+1)*CW}px;height:${(r2-r1+1)*RH}px`;d.style.setProperty('--remote',p.color);$('gridCanvas').append(d);const item=document.createElement('span');item.innerHTML=`<i style="background:${p.color}"></i>${html(userName(p.userId))} · ${html(p.address)}`;legend.append(item)})}
function liveRevision(data){if(data.revision<=state.base)return;const dirty=new Set(dirtyChanges().map(x=>x.address)),collisions=[];for(const c of data.changes)if(c.sheetId===state.sheet.id){if(dirty.has(c.address)){if(raw(c.address)!==c.value)collisions.push(c.address)}else{if(c.value)state.cells[c.address]=c.value;else delete state.cells[c.address];if(c.value)state.saved[c.address]=c.value;else delete state.saved[c.address]}}state.base=data.revision;state.revisions=data.revisions||state.revisions;$('revision').textContent=`Revision ${state.base}`;collisions.forEach(a=>state.conflicts.add(a));if(collisions.length)message(`Remote conflict in ${collisions.join(', ')}; your draft was preserved`,true);else message(`Updated from ${userName(data.userId)}`);render()}

function bind(){const grid=$('grid');grid.addEventListener('mousedown',e=>{const d=e.target.closest('.cell');if(!d)return;const p=parseAddr(d.dataset.a);if((state.editing&&$('cellEditor').value.startsWith('='))||(!state.editing&&document.activeElement===$('formulaBar')&&$('formulaBar').value.startsWith('='))){e.preventDefault();state.anchor=p;state.focus=p;state.drag=true;render();return}state.drag=true;select(p.r,p.c,e.shiftKey,false);grid.focus()});grid.addEventListener('mouseover',e=>{if(!state.drag)return;const d=e.target.closest('.cell');if(!d)return;const p=parseAddr(d.dataset.a);state.focus=p;render()});window.addEventListener('mouseup',()=>{if(state.drag){state.drag=false;if((state.editing&&$('cellEditor').value.startsWith('='))||(document.activeElement===$('formulaBar')&&$('formulaBar').value.startsWith('=')))insertReference(rangeAddress());sendPresence()}});grid.addEventListener('dblclick',e=>{if(e.target.closest('.cell'))beginEdit()});grid.addEventListener('keydown',e=>{if(state.editing)return;const key=e.key,mod=e.ctrlKey||e.metaKey;if(mod&&key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();return}if(mod&&key.toLowerCase()==='y'){e.preventDefault();redo();return}if(mod&&key.toLowerCase()==='c'){e.preventDefault();navigator.clipboard?.writeText(copyText());return}if(mod&&key.toLowerCase()==='x'){e.preventDefault();navigator.clipboard?.writeText(copyText());const x=[];eachRange(a=>x.push({address:a,value:''}));apply(x,'Cut');return}if(['Backspace','Delete'].includes(key)){e.preventDefault();const x=[];eachRange(a=>x.push({address:a,value:''}));apply(x,'Clear range');return}const dirs={ArrowUp:[-1,0],ArrowDown:[1,0],ArrowLeft:[0,-1],ArrowRight:[0,1]};if(dirs[key]){e.preventDefault();move(...dirs[key],e.shiftKey);return}if(key==='Tab'){e.preventDefault();move(0,e.shiftKey?-1:1);return}if(key==='Enter'){e.preventDefault();move(e.shiftKey?-1:1,0);return}if(key==='F2'){e.preventDefault();beginEdit();return}if(key.length===1&&!mod&&!e.altKey){e.preventDefault();beginEdit(key)}});grid.addEventListener('paste',e=>{e.preventDefault();pasteText(e.clipboardData.getData('text/plain'))});
const ed=$('cellEditor');ed.oninput=()=>{$('formulaBar').value=ed.value;formulaHelp(ed.value)};ed.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();commitEdit(e.shiftKey?-1:1)}else if(e.key==='Tab'){e.preventDefault();commitEdit();move(0,e.shiftKey?-1:1)}else if(e.key==='Escape'){e.preventDefault();cancelEdit()}};ed.onblur=e=>{if(state.editing&&!e.relatedTarget?.closest?.('#functions'))commitEdit()};
$('formulaBar').oninput=e=>formulaHelp(e.target.value);$('formulaBar').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();apply([{address:address(state.focus.r,state.focus.c),value:e.target.value}],'Edit cell');grid.focus()}else if(e.key==='Escape'){e.target.value=raw(address(state.focus.r,state.focus.c));grid.focus()}};$('commitFormula').onclick=()=>{apply([{address:address(state.focus.r,state.focus.c),value:$('formulaBar').value}],'Edit cell');grid.focus()};
$('undo').onclick=undo;$('redo').onclick=redo;$('save').onclick=save;$('go').onclick=()=>goAddress();$('nameBox').onkeydown=e=>{if(e.key==='Enter')goAddress()};$('fillDown').onclick=()=>fill('down');$('fillRight').onclick=()=>fill('right');$('clear').onclick=()=>{const x=[];eachRange(a=>x.push({address:a,value:''}));apply(x,'Clear range')};$('findNext').onclick=findNext;$('replaceOne').onclick=replaceOne;$('replaceAll').onclick=replaceAll;$('historyBtn').onclick=showHistory;$('revisionsBtn').onclick=showRevisions;$('closePanel').onclick=()=>$('panel').hidden=true;$('user').onchange=()=>sendPresence();window.addEventListener('beforeunload',()=>navigator.sendBeacon(`/api/workbooks/${state.wb.id}/presence/${sessionId}`));setInterval(sendPresence,25000)}

async function init(){try{const data=await fetch('/api/bootstrap').then(r=>r.json());state.users=data.users;state.wb=data.workbook;state.sheet=state.wb.sheets[0];state.cells={...state.sheet.cells};state.saved={...state.cells};state.base=state.wb.revision;state.revisions=data.revisions;$('title').textContent=state.wb.title;$('revision').textContent=`Revision ${state.base}`;$('user').innerHTML=state.users.map(u=>`<option value="${html(u.id)}">${html(u.name)}</option>`).join('');buildGrid();bind();sendPresence();const events=new EventSource(`/api/workbooks/${state.wb.id}/events`);events.addEventListener('presence',e=>{state.remote=JSON.parse(e.data);renderRemote()});events.addEventListener('revision',e=>liveRevision(JSON.parse(e.data));$('grid').focus()}catch(e){message(`Could not start GridForge: ${e.message}`,true)}}init();
